def test_expl_linear_coefficients() -> None:
    result = linear_explanation([0.5, -1.0, 2.0], ["a", "b", "c"], binary=True)
    assert result["method"] == "linear"
    assert result["top_features"] == ["c", "b", "a"]
    by_name = {row["feature"]: row for row in result["table"]}
    assert by_name["c"]["coefficient"] == 2.0
    assert round(by_name["c"]["odds_ratio"], 4) == round(math.exp(2.0), 4)
    regression = linear_explanation([0.5], ["a"], binary=False)
    assert regression["table"][0]["odds_ratio"] is None


def test_expl_tree_shap_with_bias_note() -> None:
    with_shap = tree_explanation(shap_available=True)
    assert with_shap["method"] == "tree_shap"
    assert with_shap["bias_note"] == ""
    without_shap = tree_explanation(shap_available=False)
    assert without_shap["method"] == "tree_importances"
    assert without_shap["bias_note"]


def test_expl_kernel_on_sampled_background() -> None:
    with_shap = kernel_explanation(500, shap_available=True)
    assert with_shap["method"] == "kernel_shap"
    assert with_shap["background_rows"] == 100
    without_shap = kernel_explanation(500, shap_available=False)
    assert without_shap["method"] == "permutation_importance"
    assert without_shap["background_rows"] == 100


def test_expl_neural_gradient_methods() -> None:
    plan = gradient_explanation()
    assert plan["method"] == "integrated_gradients"
    assert plan["baseline"] == "zeros"
    assert plan["steps"] == GRADIENT_STEPS == 32
    assert "attention maps" in plan["note"]
    panels = gradient_explanation_panels()
    assert panels["global"] == ["gradient_attributions"]
    assert panels["local"] == ["gradient_local"]


def test_expl_global_and_local_supervised() -> None:
    panels = supervised_explanation_panels()
    assert panels["global"] == ["pdp", "ice", "ale"]
    assert panels["local"] == ["shap_waterfall", "lime"]


def test_expl_clustering_surrogate() -> None:
    panels = clustering_explanation_panels()
    assert panels["cluster"] == ["centroid_heatmap", "anova_per_feature"]
    assert panels["surrogate"] == [
        "nearest_centroid_assign",
        "surrogate_tree",
        "personas",
    ]
    assert unsupervised_explanation_panels("clustering") == panels


def test_expl_embedding_panels() -> None:
    panels = embedding_explanation_panels()
    assert panels["projection"] == ["loadings_table", "biplot_coordinates"]
    assert panels["quality"] == ["reconstruction_error_per_feature"]
    assert unsupervised_explanation_panels("dimensionality_reduction") == panels


def test_expl_anomaly_panels() -> None:
    panels = anomaly_explanation_panels()
    assert panels["global"] == ["tree_shap_importances"]
    assert panels["local"] == ["per_feature_deviation"]
    assert unsupervised_explanation_panels("anomaly_detection") == panels


